    "description": "Alle Schritte für Dacquoise mit Aquafaba, mit Referenzwerten und Platz für Ihren Ansatz. Dazu Kontrollen, Ursachen und Lösungen. Zum Ausdrucken.",
    "lead": "Nutzen Sie dieses Blatt, sobald die Zutaten abgewogen sind und der Backrahmen bereitsteht. Die entscheidende Kontrolle erfolgt vor der Mandelzugabe: Stellen Sie zunächst eine stabile Baisermasse her und geben Sie erst dann die trockenen Zutaten nach und nach hinzu. Die Referenzwerte sind {dacquoise_aquafaba} g Aquafaba, {dacquoise_sugar} g Zucker und {dacquoise_minutes} Minuten bei {dacquoise_oven} °C.",
