        "q": "Kann ich dieses Blatt auch mit Pulver verwenden?",
        "a": "Ja. Rühren Sie das Pulver an, kühlen Sie es, wiegen Sie {dacquoise_aquafaba} g ab und beginnen Sie mit Schritt 1."
