    "lead": "Ihr Mayonnaiserezept funktioniert, und nun möchten Sie es im Service oder in größeren Produktionsmengen wiederholen. Die Mayonnaise mit VERY AQUAFABA beginnt mit {mayonnaise_dose} g gekühltem Aquafaba und {mayonnaise_oil} g Öl, einem Gewichtsverhältnis von Öl zu Aquafaba von {mayonnaise_oil_ratio}. Verwenden Sie dieses Rezept als Referenz, wenn Sie die Emulsion hochskalieren.",
