        "title": "3. Bis zu weichen Spitzen aufschlagen",
        "html": "<p>Für {meringue_dose} g gekühltes Aquafaba sieht die Baiser-Methode etwa {meringue_whip} Minuten bei hoher Geschwindigkeit vor. Bei weichen Spitzen bildet der Schaum beim Anheben des Schneebesens eine Spitze, die sich umbiegt. Verwendet das Rezept ein Stabilisierungsmittel, geben Sie es im vorgesehenen Schritt hinzu; im Baiserrezept werden entweder 2 g Weinstein oder 1 g Zitronensäure verwendet.</p>"
