        "id": "step-4",
        "title": "4. Zucker nach Rezept zugeben",
        "html": "<p>Für Baiser stellen Sie die Maschine auf mittlere Geschwindigkeit und lassen {meringue_sugar} g feinen Zucker esslöffelweise einrieseln. Arbeiten Sie nach Rezept weiter, bis der Schaum glänzt und feste Spitzen bildet. Mousse, Macarons und Pavlova benötigen andere Mengen; übernehmen Sie daher die Baiser-Zuckermenge nicht für andere Anwendungen.</p>"
