        "html": "<p>Bei festen Spitzen bleibt die Spitze beim Anheben des Schneebesens stehen; der Schaum ist glänzend und dicht. Gehen Sie direkt zum nächsten Rezeptschritt über. Für Baiser spritzen Sie den Schaum auf. Für Schokoladenmousse muss die Schokolade vor dem Unterheben abgekühlt sein. Für Macarons bereiten Sie Trockenmischung und Bleche vor dem Aufschlagen vor, damit Sie unmittelbar mit der Macaronage beginnen können.</p>"
