        "html": "<p>Für <a href=\"{meringue_href}\">Baiser</a> spritzen Sie die Masse auf und trocknen sie bei {meringue_bake} °C ohne Umluft für {meringue_bake_time} Stunden. Für <a href=\"{chocolate_mousse_href}\">Schokoladenmousse</a> heben Sie die Kuvertüre unter, sobald sie auf {chocolate_mousse_fold_temp} °C abgekühlt ist. Für <a href=\"{macarons_href}\">Macarons</a> heben Sie Mandelmehl und Puderzucker unter den Schaum, bis die Masse in dicken, langsamen Bändern fließt.</p>\n<p>Mayonnaise wird nicht aufgeschlagen. Hier bildet Aquafaba mit Öl eine Emulsion.</p>"
