    "lead": "Ein ganzes Ei bindet im Kuchen den Teig und liefert Feuchtigkeit. {egg_liquid} g VERY AQUAFABA übernehmen diese Aufgabe. Dafür ist kein Aufschlagen nötig: Das Aquafaba kommt zu den feuchten Zutaten. Angepasst werden muss der Wasseranteil. Aquafaba besteht zu etwa {water_aquafaba_pct} Prozent aus Wasser, ein Ei zu {water_egg_pct} Prozent. Daher werden die übrigen Flüssigkeiten um {reduce_liquids} Prozent reduziert, und das Gebäck bleibt im Ofen, bis der Kern fest ist.",
