        "title": "Wann ist die Menge von {powder_3kg_whites} Eiweißen relevant?",
        "html": "<p>Vergleichen Sie den {large_pouch_kg} kg Beutel mit den anderen Gebinden, wenn die Rezepttests abgeschlossen sind und Sie regelmäßig produzieren. Ein {medium_pouch_g} g Beutel ersetzt {powder_200g_whites} Eiweiße; der {large_pouch_kg} kg Beutel ersetzt {powder_3kg_whites}. Das entspricht {pouches_200g_in_3kg} kleineren Beuteln in einer Packung.</p>\n<p>Diese beiden Zahlen helfen beim Vergleich: Prüfen Sie, wie oft Sie den {medium_pouch_g} g Beutel ersetzen und ob diese Größe noch zu Ihrem Produktionsumfang passt. Niemand rührt {powder_3kg_whites} Eiweiße auf einmal an. Der Beutel ermöglicht wiederholte Produktionsläufe mit derselben Dosierung pro Rezept, ohne jeweils eine kleine Packung öffnen zu müssen.</p>"
